-- 0004_metric_seed: the metric catalogue from docs/ingest-contract.md plus the lab markers.
-- GENERATED from MetricSeed.cs (MetricSeedTests checks for drift). Edit the C# list, then regenerate.
-- Idempotent: re-running updates display text and classification but never removes a key.

ON CONFLICT (key) DO UPDATE SET
  unit = EXCLUDED.unit,
  kind = EXCLUDED.kind,
  category = EXCLUDED.category,
  display_name = EXCLUDED.display_name,
  blurb = EXCLUDED.blurb,
  good_direction = EXCLUDED.good_direction,
  loinc = EXCLUDED.loinc,
  value_labels = EXCLUDED.value_labels,
  sex_applicability = EXCLUDED.sex_applicability;
